"""Practical buying guides with paired English/French copy and visible sources."""
from bilingual import translations, key

def copy(en,fr):
 translations[key(en)]=fr
 return en

def para(en,fr):return '<p>'+esc(copy(en,fr))+'</p>'
def heading(en,fr):return '<h3>'+esc(copy(en,fr))+'</h3>'
def section(identifier,en,fr,body):return f'<section id="{identifier}"><h2>'+esc(copy(en,fr))+'</h2>'+body+'</section>'
def table(headers,rows):
 return '<div class="table-scroll" tabindex="0" role="region" aria-label="'+esc(copy('Comparison table','Tableau comparatif'))+'"><table><thead><tr>'+''.join('<th scope="col">'+esc(copy(*h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+esc(copy(*cell))+('</th>' if i==0 else '</td>') for i,cell in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
def source(url,en,fr):return '<p class="guide-source">'+esc(copy('Reference:','Référence :'))+' '+link(url,esc(copy(en,fr)))+'</p>'
def checklist(items):return '<ul class="guide-checklist">'+''.join('<li>'+esc(copy(en,fr))+'</li>' for en,fr in items)+'</ul>'

def guide(path,title,description,intro,sections,need,cta):
 title=copy(*title);description=copy(*description)
 body='<header class="guide-hero wrap"><p class="eyebrow">'+copy('THE WAVING.CA BUYING GUIDES','LES GUIDES D’ACHAT WAVING.CA')+'</p><h1>'+esc(title)+'</h1><p class="lead">'+esc(copy(*intro))+'</p></header>'
 body+='<div class="guide-layout wrap"><aside class="guide-toc" aria-label="'+copy('On this page','Sur cette page')+'"><p>'+copy('IN THIS GUIDE','DANS CE GUIDE')+'</p>'+''.join(link('#'+sid,esc(copy(en,fr))) for sid,en,fr,_ in sections)+'</aside><article class="guide-body">'
 body+=''.join(section(*s) for s in sections)
 body+='<section class="guide-quote"><h2>'+copy('Put the guide to work.','Passez du guide au projet.')+'</h2>'+para('Tell us what you know so far. We can help clarify the remaining details in your quote.','Indiquez ce que vous savez déjà. Nous pourrons préciser les autres détails dans votre soumission.')+button(copy(*cta),need)+'<p>'+link('/resources/',copy('ALL BUYING GUIDES','TOUS LES GUIDES D’ACHAT'),'text-link')+'</p></section></article></div>'
 add(path,title,description,body)

size=para('Choose a flag that fits both the design’s proportions and the pole’s approved flag capacity. Measure an existing flag from the ground when it is safely lowered; pole height alone is not a load rating.','Choisissez un drapeau adapté aux proportions du dessin et à la capacité approuvée du mât. Mesurez un drapeau existant au sol, une fois abaissé en toute sécurité; la hauteur du mât n’indique pas sa capacité de charge.')
size+=para('Canada’s National Flag uses a 2:1 length-to-height ratio. Canadian Heritage gives these examples for exterior permanent poles:','Le drapeau national du Canada présente un rapport longueur-hauteur de 2:1. Patrimoine canadien donne ces exemples pour les mâts extérieurs permanents :')
size+=table([('Flag: height × length','Drapeau : hauteur × longueur'),('Pole height','Hauteur du mât')],[
 [('0.90 × 1.80 m','0,90 × 1,80 m'),('5.10–6 m','5,10–6 m')],
 [('1.40 × 2.80 m','1,40 × 2,80 m'),('9–10.50 m','9–10,50 m')],
 [('1.80 × 3.60 m','1,80 × 3,60 m'),('12–13.50 m','12–13,50 m')]])
size+=para('These are display proportions, not engineering approval or a list of stocked sizes. Confirm the pole manufacturer’s limits, site exposure and attachment system before ordering.','Ces dimensions concernent la présentation; elles ne constituent ni une approbation technique ni une liste de formats en stock. Confirmez les limites du fabricant du mât, l’exposition du site et le système de fixation avant de commander.')
size+=source('https://www.canada.ca/en/canadian-heritage/services/flag-canada-etiquette/flying-rules.html','Canadian Heritage: flying the National Flag','Patrimoine canadien : déploiement du drapeau national')
fabric=para('Nylon is generally lighter and moves readily in a light breeze. Two-ply spun polyester is often considered for more exposed, continuous displays. The fabric construction matters as much as the material name.','Le nylon est généralement plus léger et flotte facilement dans une brise légère. Le polyester filé à deux plis est souvent envisagé pour une exposition continue dans des lieux plus exposés. La construction du tissu compte autant que le nom de la matière.')
fabric+=table([('Option to discuss','Option à discuter'),('What to confirm','Points à confirmer')],[
 [('Nylon','Nylon'),('Fabric weight, outdoor suitability, colour treatment and edge finishing.','Poids du tissu, aptitude à l’extérieur, traitement des couleurs et finition des bords.')],
 [('Two-ply spun polyester','Polyester filé à deux plis'),('Suitability for your exposure and compatibility with the pole’s flag capacity.','Adaptation à l’exposition du site et compatibilité avec la capacité du mât.')],
 [('Printed custom fabric','Tissu imprimé personnalisé'),('Exact fabric, print method, viewing sides and intended indoor or outdoor use.','Tissu exact, procédé d’impression, faces visibles et usage intérieur ou extérieur prévu.')]])
fabric+=para('Availability and specifications are confirmed in the quote. No fabric has a guaranteed lifespan in every location.','Les disponibilités et spécifications sont confirmées dans la soumission. Aucun tissu n’offre une durée de vie garantie dans toutes les conditions.')
fabric+=source('https://annin.com/products/us-flags/outdoor-flags-sets/','Annin Flagmakers: outdoor fabric characteristics','Annin Flagmakers : caractéristiques des tissus extérieurs')
finishing=para('Match the flag’s attachment to the existing hardware. A heading with grommets, a sleeve and a rope heading are different specifications; they should not be treated as interchangeable.','Adaptez la fixation du drapeau à la quincaillerie existante. Une sangle à œillets, un fourreau et une sangle avec cordage sont des spécifications différentes; elles ne sont pas interchangeables.')
finishing+=checklist([('Send a close-up of the existing attachment, taken safely from ground level.','Joignez une photo de la fixation existante, prise en toute sécurité depuis le sol.'),('For a sleeve, confirm the pole diameter and required sleeve opening.','Pour un fourreau, confirmez le diamètre du mât et l’ouverture nécessaire.'),('For custom flags, specify whether the reverse may show a mirrored image or needs a separately readable design.','Pour les drapeaux personnalisés, précisez si le verso peut présenter une image inversée ou doit être lisible séparément.')])
brief=checklist([('Flag design, quantity and dimensions, or a photo of the existing display.','Dessin, quantité et dimensions du drapeau, ou photo de l’installation existante.'),('Indoor or outdoor use, location and approximate pole height.','Usage intérieur ou extérieur, emplacement et hauteur approximative du mât.'),('Preferred delivery date and any approved custom artwork.','Date de livraison souhaitée et tout visuel personnalisé approuvé.')])
brief+=para('A useful quote identifies the material, size, finish, quantity, delivery arrangements and any artwork work. Compare those details alongside the total price.','Une soumission utile précise la matière, le format, la finition, la quantité, les modalités de livraison et les éventuels travaux graphiques. Comparez ces détails avec le prix total.')
guide('/resources/choosing-a-flag/',('Choosing a flag: size, fabric & finishing','Choisir un drapeau : format, tissu et finition'),('Compare flag sizes, nylon and polyester, attachment styles and custom artwork requirements before requesting a quote.','Comparez les formats, le nylon et le polyester, les fixations et les besoins graphiques avant de demander une soumission.'),('Start with where the flag will fly, how it attaches and when you need it. Those details make the choice clearer.','Commencez par le lieu d’utilisation, le type de fixation et la date souhaitée. Ces détails facilitent le choix.'),[('size','What size flag do I need?','Quel format de drapeau choisir?',size),('fabric','Which fabric should I consider?','Quel tissu envisager?',fabric),('finishing','Which finishing will fit?','Quelle finition convient?',finishing),('brief','What belongs in a flag quote?','Que doit comprendre une soumission?',brief)],'Buy%20Flags',('GET A FLAG QUOTE','OBTENIR UNE SOUMISSION DE DRAPEAUX'))

pole_setting=para('Start with the intended flag, the display position and access for everyday operation. For an existing installation, share the model or product records if available before selecting a replacement pole.','Commencez par le drapeau prévu, l’emplacement et l’accès pour les opérations courantes. Pour une installation existante, transmettez le modèle ou les documents du produit, si disponibles, avant de choisir un mât de remplacement.')
pole_setting+=checklist([('Permanent ground display, building-mounted display or portable event setup.','Installation permanente au sol, fixation au bâtiment ou dispositif événementiel portatif.'),('Flag dimensions and number of flags in the planned display.','Dimensions des drapeaux et nombre prévu dans l’installation.'),('Nearby trees, buildings, circulation routes and service access.','Arbres, bâtiments, voies de circulation et accès pour l’entretien à proximité.')])
operation=table([('System','Système'),('How it operates','Fonctionnement'),('Decision to make','Choix à faire')],[
 [('External halyard','Drisse extérieure'),('The rope runs outside the pole.','Le cordage passe à l’extérieur du mât.'),('Where can the cleat be reached and secured?','Où le taquet sera-t-il accessible et sécurisé?')],
 [('Internal halyard','Drisse intérieure'),('The operating system runs inside the pole.','Le système de manœuvre passe à l’intérieur du mât.'),('Who needs access to the operating point and any keys?','Qui doit accéder au point de manœuvre et aux éventuelles clés?')],
 [('Portable system','Système portatif'),('The pole and base form a temporary display.','Le mât et sa base forment une installation temporaire.'),('Which surface, footprint and operating conditions are approved?','Quels sols, encombrements et conditions d’utilisation sont approuvés?')]])
pole_specs=para('Compare complete product specifications, not just height or material. Ask for the rated flag capacity, applicable exposure limits, finish, operating hardware and maintenance instructions for the exact model.','Comparez les spécifications complètes, pas seulement la hauteur ou la matière. Demandez la capacité nominale, les limites d’exposition, la finition, la quincaillerie de manœuvre et les consignes d’entretien du modèle exact.')
pole_specs+=para('A foundation, bracket or base must suit the selected pole and its site. An existing foundation should be assessed before it is reused. Any required engineering, approvals or site preparation should be identified in the installation scope.','Une fondation, un support ou une base doit convenir au mât choisi et à son emplacement. Une fondation existante doit être évaluée avant réutilisation. Les besoins en ingénierie, autorisations ou préparation doivent être précisés dans la portée de l’installation.')
pole_cost=para('Separate the pole and hardware from delivery, access equipment, foundation work, installation and ongoing servicing. This makes proposals easier to compare.','Distinguez le mât et la quincaillerie de la livraison, des équipements d’accès, de la fondation, de l’installation et de l’entretien. Les propositions seront ainsi plus faciles à comparer.')
pole_cost+='<p>'+link('/resources/installation-cost/',copy('See what affects installation cost.','Découvrez les facteurs qui influencent le coût d’installation.'))+'</p>'
guide('/resources/choosing-a-flagpole/',('Choosing a flagpole for your site','Choisir un mât pour votre site'),('Compare flagpole operating systems, site requirements, specifications and installation scope.','Comparez les systèmes de manœuvre, les exigences du site, les spécifications et la portée de l’installation.'),('The right pole brings the display, the site and the people operating it together. Use these questions to prepare a useful brief.','Le bon mât tient compte de l’installation, du site et des personnes qui le manœuvrent. Préparez votre demande à l’aide de ces questions.'),[('setting','What is the display for?','À quoi servira l’installation?',pole_setting),('operation','Internal or external halyard?','Drisse intérieure ou extérieure?',operation),('specifications','Which specifications matter?','Quelles spécifications vérifier?',pole_specs),('scope','What should the quote include?','Que devrait inclure la soumission?',pole_cost)],'Buy%20Flagpole',('PLAN MY FLAGPOLE','PLANIFIER MON MÂT'))

cost_answer=para('An installed flagpole price combines the pole and hardware with the work needed at your site. Ground conditions, foundation requirements, access and the display specification can change that scope, so a pole-only price is not an installed total.','Le prix d’un mât installé combine le mât et la quincaillerie avec les travaux nécessaires sur place. Le sol, la fondation, l’accès et les spécifications peuvent modifier la portée; un prix de mât seul ne représente donc pas le coût total installé.')
cost_answer+=para('Waving.ca confirms project pricing through a quote. Share your location, intended display and site photos to help define the work before comparing totals.','Waving.ca confirme les prix par soumission. Transmettez l’emplacement, l’installation prévue et des photos du site pour préciser les travaux avant de comparer les montants.')
cost_rows=table([('Cost component','Poste de coût'),('What changes the scope','Ce qui modifie la portée')],[
 [('Pole & hardware','Mât et quincaillerie'),('Height, finish, operating system, flag and attachments.','Hauteur, finition, système de manœuvre, drapeau et fixations.')],
 [('Site preparation','Préparation du site'),('Ground conditions, existing foundations and removal of an old installation.','Sol, fondations existantes et retrait d’une ancienne installation.')],
 [('Access & installation','Accès et installation'),('Equipment access, working area, scheduling and installation method.','Accès des équipements, aire de travail, calendrier et méthode d’installation.')],
 [('Delivery & reinstatement','Livraison et remise en état'),('Location, transport, disposal and restoration of affected surfaces.','Emplacement, transport, élimination et remise en état des surfaces touchées.')]])
compare=checklist([('Is the flag, operating hardware and installation included?','Le drapeau, la quincaillerie de manœuvre et l’installation sont-ils inclus?'),('Who handles site checks, any required approvals and foundation work?','Qui s’occupe des vérifications du site, des autorisations requises et de la fondation?'),('Are delivery, removal, disposal, surface restoration and taxes itemized?','La livraison, le retrait, l’élimination, la remise en état et les taxes sont-ils détaillés?'),('Which exclusions, access assumptions and scheduling conditions apply?','Quelles exclusions, hypothèses d’accès et conditions de calendrier s’appliquent?')])
prepare=para('You do not need to settle every specification before contacting us. A city or postal code, approximate height, new or replacement installation, and ground-level photos are a useful starting point.','Vous n’avez pas besoin de fixer toutes les spécifications avant de nous contacter. La ville ou le code postal, la hauteur approximative, le type d’installation — neuve ou de remplacement — et des photos prises au sol constituent un bon départ.')
prepare+=para('For a replacement, include any existing product records. Do not assume the old foundation or hardware can be reused until their suitability has been reviewed.','Pour un remplacement, joignez les documents du produit existant. Ne présumez pas que la fondation ou la quincaillerie peut être réutilisée avant une vérification de compatibilité.')
guide('/resources/installation-cost/',('What affects flagpole installation cost?','Qu’est-ce qui influence le coût d’installation d’un mât?'),('Understand flagpole installation cost factors and compare quote inclusions, site preparation, delivery and access.','Comprenez les facteurs de coût et comparez les inclusions, la préparation du site, la livraison et l’accès.'),('Compare the complete installed scope. A clear breakdown is more useful than a price that leaves the site work undefined.','Comparez la portée complète des travaux. Une ventilation claire est plus utile qu’un prix qui ne précise pas les travaux sur place.'),[('price','Why is a site-specific quote needed?','Pourquoi une soumission propre au site?',cost_answer),('factors','What changes the cost?','Qu’est-ce qui fait varier le coût?',cost_rows),('compare','How do I compare proposals?','Comment comparer les propositions?',compare),('prepare','What can I send now?','Que puis-je transmettre maintenant?',prepare)],'Flagpole%20Installation',('REQUEST INSTALLATION PRICING','DEMANDER UN PRIX D’INSTALLATION'))

rental_package=para('A rental may be a flag only, a flag with a compatible pole and base, or a display with requested delivery and setup. Tell us which pieces and services you need; the confirmed quote defines what is included.','Une location peut comprendre un drapeau seul, un drapeau avec un mât et une base compatibles, ou une installation avec livraison et montage demandés. Indiquez les éléments et services souhaités; la soumission confirmée précise les inclusions.')
rental_package+=table([('Package to request','Formule à demander'),('Useful when…','Utile lorsque…')],[
 [('Flag only','Drapeau seul'),('You already have suitable, compatible poles or stands.','Vous disposez déjà de mâts ou supports adaptés et compatibles.')],
 [('Flag, pole & base','Drapeau, mât et base'),('You need a complete temporary display system.','Vous avez besoin d’une installation temporaire complète.')],
 [('Display with logistics','Installation et logistique'),('You also need delivery, setup, collection or removal.','Vous avez aussi besoin de livraison, montage, ramassage ou démontage.')]])
rental_dates=para('Include the first day the equipment must be available and the day it can be collected. Setup, rehearsals and teardown can extend the period beyond the public event dates.','Indiquez le premier jour où le matériel doit être disponible et celui où il peut être ramassé. Montage, répétitions et démontage peuvent prolonger la période au-delà des dates publiques de l’événement.')
rental_dates+=para('Share your dates early. Minimum rental periods, availability, transport timing and any changes or cancellation terms are confirmed for the request.','Transmettez vos dates tôt. La durée minimale, les disponibilités, les délais de transport et les conditions de modification ou d’annulation sont confirmés pour chaque demande.')
rental_venue=checklist([('Indoor or outdoor setting, floor or ground surface and proposed positions.','Intérieur ou extérieur, type de sol et emplacements envisagés.'),('Venue access times, loading arrangements and pedestrian clearances.','Heures d’accès, modalités de livraison et dégagements pour les piétons.'),('Flag designs, quantities, dimensions and approved artwork if custom.','Dessins, quantités, dimensions et visuels approuvés pour les drapeaux personnalisés.'),('Venue permissions and any weather or operating restrictions.','Autorisations du lieu et éventuelles restrictions météorologiques ou d’utilisation.')])
rental_venue+=para('A temporary base is not suitable for every setting. The selected equipment and operating plan must match the venue and conditions.','Une base temporaire ne convient pas à toutes les situations. Le matériel choisi et le plan d’utilisation doivent correspondre au lieu et aux conditions.')
rental_total=para('Check the quantities, rental period, included hardware, delivery and collection windows, setup responsibilities, taxes and any deposit or damage terms. Confirm availability before relying on the display in an event plan.','Vérifiez les quantités, la période, la quincaillerie incluse, les créneaux de livraison et ramassage, les responsabilités de montage, les taxes et les conditions de dépôt ou de dommages. Confirmez les disponibilités avant d’intégrer l’installation au plan de l’événement.')
guide('/resources/rental-planning/',('Planning an event flag rental','Planifier une location de drapeaux pour un événement'),('Compare flag rental packages and prepare event dates, venue information, quantities and delivery requirements.','Comparez les formules de location et préparez les dates, les renseignements sur le lieu, les quantités et les besoins de livraison.'),('Start with the full rental period, your venue and the display you want. Then confirm the equipment and logistics together.','Commencez par la période complète, le lieu et l’installation souhaitée. Confirmez ensuite le matériel et la logistique ensemble.'),[('package','What can a rental include?','Que peut comprendre une location?',rental_package),('dates','Which dates should I provide?','Quelles dates fournir?',rental_dates),('venue','What does the venue need?','Que faut-il préciser sur le lieu?',rental_venue),('confirm','What should I confirm before booking?','Que confirmer avant de réserver?',rental_total)],'Flag%20Rental',('PLAN MY RENTAL','PLANIFIER MA LOCATION'))

GUIDES=[('/resources/choosing-a-flag/','Choosing a flag','Choisir un drapeau','Compare size, fabric and finishing.','Comparez formats, tissus et finitions.'),('/resources/choosing-a-flagpole/','Choosing a flagpole','Choisir un mât','Plan the display, operation and site requirements.','Planifiez la présentation, la manœuvre et les besoins du site.'),('/resources/installation-cost/','Installation cost guide','Guide des coûts d’installation','Understand the scope behind the price.','Comprenez les travaux qui déterminent le prix.'),('/resources/rental-planning/','Planning an event flag rental','Planifier une location événementielle','Get the dates, equipment and logistics right.','Précisez les dates, le matériel et la logistique.')]
guide_cards=cards([(copy(en,fr),url,copy(desc,descfr)) for url,en,fr,desc,descfr in GUIDES],'guide-cards')
hub='<header class="guide-hero wrap"><p class="eyebrow">'+copy('BUYING GUIDES','GUIDES D’ACHAT')+'</p><h1>'+copy('Make the next choice clearer.','Faites le prochain choix en confiance.')+'</h1>'+para('Practical comparisons and checklists for flags, flagpoles, installation and rentals. Start with the decision in front of you.','Comparaisons et listes pratiques pour les drapeaux, mâts, installations et locations. Commencez par le choix qui vous attend.')+'</header><section class="wrap guide-hub">'+guide_cards+'</section>'
hub+='<section class="wrap section">'+section_head(copy('AFTER THE PURCHASE','APRÈS L’ACHAT'),copy('Care & flag etiquette.','Entretien et étiquette.'))+cards([(copy('Looking after your flags','Entretenir vos drapeaux'),'/resources/flag-care/',copy('Recognize wear and plan useful replacements.','Repérez l’usure et planifiez les remplacements.')),(copy('Canadian flag etiquette','Étiquette du drapeau canadien'),'/resources/flag-etiquette/',copy('Find the official guidance for your display.','Consultez les consignes officielles pour votre installation.'))])+'</section>'
add('/resources/',copy('Flag & flagpole buying guides','Guides d’achat de drapeaux et de mâts'),copy('Buying guides for flag sizes and fabrics, flagpoles, installation costs and event rentals, plus care and etiquette resources.','Guides d’achat : formats et tissus, mâts, coûts d’installation et locations événementielles, avec des ressources d’entretien et d’étiquette.'),hub)
for paths,index in [(['/flags/','/flags/canada/','/custom-flags/'],0),(['/flagpoles/'],1),(['/flagpole-installation/'],2),(['/flag-rentals/'],3)]:
 url,en,fr,desc,descfr=GUIDES[index]
 callout='<aside class="guide-callout wrap"><span>'+copy('A LITTLE HELP CHOOSING','POUR VOUS AIDER À CHOISIR')+'</span><a href="'+url+'"><strong>'+copy(en,fr)+'</strong><span>'+copy(desc,descfr)+' <span aria-hidden="true">→</span></span></a></aside>'
 for path in paths:PAGES[path]['body']=PAGES[path]['body'].replace('</section>','</section>'+callout,1)
# Put a compact route to the guide hub beside the homepage project choices.
PAGES['/']['body']=PAGES['/']['body'].replace('<section class="wrap section"><div class="section-title-row">','<div class="wrap guide-home-link">'+link('/resources/',copy('Need help choosing? Explore the buying guides.','Besoin d’aide pour choisir? Consultez les guides d’achat.'))+'</div><section class="wrap section"><div class="section-title-row">',1)
